$SoftwareSelection_Form_OK.Add_Click{
    $SoftwareSelection_Form.Topmost = $false
    if ($SoftwareSelection_CheckBoxes['Microsoft Store'].Checked) {
        [Console]::BackgroundColor = 'Black'; [Console]::ForegroundColor = 'Green'; [Console]::Write('Installing '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'Microsoft Store'"); [Console]::ResetColor(); [Console]::WriteLine()
        wsreset -i
    }

    if ($SoftwareSelection_CheckBoxes['Uninstall Microsoft Store'].Checked) {
        [Console]::BackgroundColor = 'Black'; [Console]::ForegroundColor = 'Green'; [Console]::Write('Uninstalling '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'Microsoft Store'"); [Console]::ResetColor(); [Console]::WriteLine()
        Get-AppxPackage -AllUsers 'Microsoft.WindowsStore' | Remove-AppxPackage -ErrorAction SilentlyContinue
        Get-AppxPackage -AllUsers 'Microsoft.StorePurchaseApp' | Remove-AppxPackage -ErrorAction SilentlyContinue
    }

    if ($SoftwareSelection_CheckBoxes['NordVPN'].Checked) {
        $NordVPN_DDL = 'https://downloads.nordcdn.com/apps/windows/NordVPN/latest/NordVPNInstall.exe'
        $NordVPN_Filename = [IO.Path]::GetFileName(([URI]$NordVPN_DDL).AbsolutePath)
        $NordVPN_SavePath = [IO.Path]::Combine($env:TEMP, $NordVPN_Filename)
        [Console]::BackgroundColor = 'Black'; [Console]::ForegroundColor = 'Green'; [Console]::Write('Downloading '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'NordVPN'"); [Console]::ForegroundColor = 'Green'; [Console]::Write(' from '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'$NordVPN_DDL'"); [Console]::ForegroundColor = 'Green'; [Console]::Write(' to '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'$NordVPN_SavePath'"); [Console]::ResetColor(); [Console]::WriteLine()
        (New-Object System.Net.WebClient).DownloadFile($NordVPN_DDL, $NordVPN_SavePath)

        $NordVPN_Argument = '/verysilent'
        [Console]::BackgroundColor = 'Black'; [Console]::ForegroundColor = 'Green'; [Console]::Write('Installing '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'NordVPN'"); [Console]::ForegroundColor = 'Green'; [Console]::Write(' from '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'$NordVPN_SavePath'"); [Console]::ForegroundColor = 'Green'; [Console]::Write(' with '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'$NordVPN_Argument'"); [Console]::ResetColor(); [Console]::WriteLine()
        Start-Process $NordVPN_SavePath -ArgumentList $NordVPN_Argument
    }

    if ($SoftwareSelection_CheckBoxes['Minecraft Launcher'].Checked) {
        $Minecraft_DDL = 'https://launcher.mojang.com/download/MinecraftInstaller.msi'
        $Minecraft_Filename = [IO.Path]::GetFileName(([URI]$Minecraft_DDL).AbsolutePath)
        $Minecraft_SavePath = [IO.Path]::Combine($env:TEMP, $Minecraft_Filename)
        [Console]::BackgroundColor = 'Black'; [Console]::ForegroundColor = 'Green'; [Console]::Write('Downloading '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'Minecraft Launcher'"); [Console]::ForegroundColor = 'Green'; [Console]::Write(' from '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'$Minecraft_DDL'"); [Console]::ForegroundColor = 'Green'; [Console]::Write(' to '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'$Minecraft_SavePath'"); [Console]::ResetColor(); [Console]::WriteLine()
